#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <WiFi.h>
#include <Adafruit_NeoPixel.h>
#include <Adafruit_BME280.h>
#include <SPI.h>
#include <FastLED.h>
#include <DallasTemperature.h>
#include <Keypad.h>

// --- Настройки OLED ---
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
#define SCREEN_ADDRESS 0x3C // Стандартный адрес для SSD1306

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// --- Настройки кнопок ---
#define BTN_UP 1     // Пин для кнопки "Вверх"
#define BTN_DOWN 2   // Пин для кнопки "Вниз"
#define BTN_SELECT 0 // Пин для кнопки "Выбор" (обновить список)

// --- Переменные для работы ---
int networkCount = 0;
int selectedNetwork = 0;
bool needsRedraw = true;

void setup() {
  Serial.begin(115200);

  // Инициализация кнопок с подтяжкой к питанию
  pinMode(BTN_UP, INPUT_PULLUP);
  pinMode(BTN_DOWN, INPUT_PULLUP);
  pinMode(BTN_SELECT, INPUT_PULLUP);

  // Инициализация OLED
  if(!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println(F("SSD1306 allocation failed"));
    for(;;); // Остановка, если дисплей не найден
  }
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);

  // Настройка Wi-Fi в режим станции
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);

  // Первое сканирование
  scanWiFi();
}

void loop() {
  // Обработка кнопок
  if (digitalRead(BTN_UP) == LOW) {
    if (selectedNetwork > 0) selectedNetwork--;
    needsRedraw = true;
    delay(200); // Простая защита от дребезга
  }

  if (digitalRead(BTN_DOWN) == LOW) {
    if (selectedNetwork < networkCount - 1) selectedNetwork++;
    needsRedraw = true;
    delay(200);
  }

  if (digitalRead(BTN_SELECT) == LOW) {
    scanWiFi(); // Обновление списка
    selectedNetwork = 0;
    needsRedraw = true;
    delay(200);
  }

  // Перерисовка экрана только при необходимости
  if (needsRedraw) {
    drawMenu();
    needsRedraw = false;
  }
}

// --- Функция сканирования ---
void scanWiFi() {
  display.clearDisplay();
  display.setCursor(0, 0);
  display.println("Scanning...");
  display.display();

  networkCount = WiFi.scanNetworks();

  // Ограничиваем количество отображаемых сетей, чтобы не переполнить буфер
  if (networkCount > 5) {
    networkCount = 5;
  }
}

// --- Функция отрисовки меню ---
void drawMenu() {
  display.clearDisplay();

  if (networkCount == 0) {
    display.setCursor(0, 0);
    display.println("No networks found");
    display.display();
    return;
  }

  // Отрисовка списка сетей
  for (int i = 0; i < networkCount; i++) {
    int yPos = i * 12; // Позиция строки

    // Выделение выбранной сети (инвертированный прямоугольник)
    if (i == selectedNetwork) {
      display.fillRect(0, yPos, 128, 12, SSD1306_WHITE);
      display.setTextColor(SSD1306_BLACK);
    } else {
      display.setTextColor(SSD1306_WHITE);
    }

    display.setCursor(0, yPos + 2);
    // Выводим SSID (обрезаем, если слишком длинный)
    String ssid = WiFi.SSID(i);
    if (ssid.length() > 16) ssid = ssid.substring(0, 16);
    display.print(ssid);

    // Выводим уровень сигнала справа
    display.setCursor(100, yPos + 2);
    display.print(WiFi.RSSI(i));
  }

  display.display();
}
